package com.primehr.succession.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import com.primehr.shared.exception.IllegalLifecycleTransitionException;import jakarta.persistence.*;import java.time.*;
@Entity @Table(name="succession_continuity_risk_review",uniqueConstraints=@UniqueConstraint(name="uk_succession_risk_cycle_position",columnNames={"agency_id","cycle_id","designation_id"}))
public class SuccessionContinuityRiskReview extends RspAuditedEntity{
 public enum RiskLevel{LOW,MODERATE,HIGH,CRITICAL} public enum Status{DRAFT,FINALIZED}
 @Column(name="cycle_id",nullable=false,length=36)private String cycleId;@Column(name="designation_id",nullable=false,length=36)private String designationId;@Column(name="target_type",nullable=false,length=20)private String targetType;@Column(name="target_id",nullable=false)private Long targetId;@Column(name="job_position_id",nullable=false)private Long jobPositionId;@Column(name="position_name",nullable=false,length=250)private String positionName;@Column(name="plantilla_id")private Long plantillaId;@Column(name="plantilla_name",length=250)private String plantillaName;@Column(name="target_fingerprint",nullable=false,length=120)private String targetFingerprint;@Enumerated(EnumType.STRING)@Column(name="risk_level",nullable=false,length=20)private RiskLevel riskLevel;@Column(name="risk_reason",nullable=false,length=4000)private String riskReason;@Column(name="continuity_controls",nullable=false,length=4000)private String continuityControls;@Column(name="review_date",nullable=false)private LocalDate reviewDate;@Column(name="next_review_date",nullable=false)private LocalDate nextReviewDate;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private Status status;@Column(name="finalized_by",length=100)private String finalizedBy;@Column(name="finalized_at")private Instant finalizedAt;
 protected SuccessionContinuityRiskReview(){} public SuccessionContinuityRiskReview(String a,String cycle,SuccessionCriticalPositionDesignation d,RiskLevel level,String reason,String controls,LocalDate review,LocalDate next){super(a);cycleId=requiredText(cycle,"cycleId");designationId=d.getId();targetType=d.getTargetType().name();targetId=d.getTargetId();jobPositionId=d.getJobPositionId();positionName=d.getPositionName();plantillaId=d.getPlantillaId();plantillaName=d.getPlantillaName();targetFingerprint=d.getSourceFingerprint();status=Status.DRAFT;update(level,reason,controls,review,next);}
 public void update(RiskLevel level,String reason,String controls,LocalDate review,LocalDate next){if(status!=Status.DRAFT)throw new IllegalLifecycleTransitionException("Only draft risk reviews may be changed");if(review==null||next==null||next.isBefore(review))throw new IllegalArgumentException("nextReviewDate must be on or after reviewDate");riskLevel=java.util.Objects.requireNonNull(level);riskReason=requiredText(reason,"riskReason");continuityControls=requiredText(controls,"continuityControls");reviewDate=review;nextReviewDate=next;}
 public void finalizeReview(String actor,Instant at){if(status!=Status.DRAFT)throw new IllegalLifecycleTransitionException("Only draft risk reviews may be finalized");status=Status.FINALIZED;finalizedBy=requiredText(actor,"actor");finalizedAt=at;}
 public String getCycleId(){return cycleId;}public String getDesignationId(){return designationId;}public String getTargetType(){return targetType;}public Long getTargetId(){return targetId;}public Long getJobPositionId(){return jobPositionId;}public String getPositionName(){return positionName;}public Long getPlantillaId(){return plantillaId;}public String getPlantillaName(){return plantillaName;}public String getTargetFingerprint(){return targetFingerprint;}public RiskLevel getRiskLevel(){return riskLevel;}public String getRiskReason(){return riskReason;}public String getContinuityControls(){return continuityControls;}public LocalDate getReviewDate(){return reviewDate;}public LocalDate getNextReviewDate(){return nextReviewDate;}public Status getStatus(){return status;}public String getFinalizedBy(){return finalizedBy;}public Instant getFinalizedAt(){return finalizedAt;}
}
